-- Separate account-wide storage from existing character-owned storage.
-- Existing character storage rows and balances are intentionally unchanged.
ALTER TABLE "account"
    ADD COLUMN "storage_money" bigint NOT NULL DEFAULT 0,
    ADD COLUMN "storage_slots" integer NOT NULL DEFAULT 160,
    ADD CONSTRAINT "account_storage_money_positive" CHECK ("storage_money" >= 0),
    ADD CONSTRAINT "account_storage_slots_positive" CHECK ("storage_slots" >= 160);

CREATE TABLE "account_storage"
(
    "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "owner_id" integer NOT NULL REFERENCES "account" ("id") ON DELETE CASCADE,
    "item_id" integer NOT NULL REFERENCES "item" ("id") ON DELETE CASCADE,
    "slot" integer NOT NULL,
    "quantity" smallint NOT NULL DEFAULT 1,
    UNIQUE ("owner_id", "slot"),
    CONSTRAINT "account_storage_slot_positive" CHECK ("slot" >= 0),
    CONSTRAINT "account_storage_quantity_positive" CHECK ("quantity" >= 0)
);

CREATE INDEX "account_storage_item_id_index" ON "account_storage" ("item_id");
